    mem_wdata_i = '0;
    mem_we_i = '0;
    sim_cycles = 0;
    timer_generation = 0;
    timer_deadline = NO_TIMER;
    timer_owner_target = NO_TIMER;
    iterations = 10000;
    status = 0;
    track_falling_edges = 1'b0;
    clock_drivers_active = 1'b0;
`ifdef CPPTB_SV_DPI_TIMING
    phase_requests = 0;
    phase_barrier_token = 1'b0;
    last_started_time = $time;
`endif
    void'($value$plusargs("AUTHORING_CORE_ITERS=%d", iterations));

    for (int i = 0; i < INPUT_WORD_COUNT; i++) begin
      in_words[i] = '0;
    end
    for (int i = 0; i < OUTPUT_WORD_COUNT; i++) begin
      out_words[i] = '0;
    end
    for (int i = 0; i < CPPTB_SIGNAL_COUNT; i++) begin
      edge_interest[i] = '0;
      registered_clock[i] = 1'b0;
      primary_clock[i] = 1'b0;
    end

    authoring_core_dpi_init(iterations, TIMEPRECISION_FS);
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
    calendar_initialize();
`endif
    run_step(PHASE_INIT, NO_SIGNAL, EDGE_RISING, initial_requests);
    service_requests(initial_requests);
    clock_drivers_active = 1'b1;
    if (status == 0) begin
      fork
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
        calendar_owner();
`else
        timer_owner();
`ifdef CPPTB_SV_DPI_TIMING
        phase_pump();
`endif
        drive_clock_0();
`endif
        observe_signal_0();
      join_none
    end

    wait (status != 0);
    timer_generation++;
    if (status < 0) begin
      $fatal(1, "authoring_core_dut DPI testbench failed");
    end
    $finish;
  end

